<script>
    function filterTable() {
        var selectedCategory = event.target.value;
        var tableRows = document.querySelectorAll('#dynamicDataBody tr'); // Target the dynamic data tbody

        if (tableRows.length === 0) {
            console.error('No table rows found in the dynamic data tbody.');
            return; // Exit the function if no table rows are found
        }

        var row_5 = 0, row_7 = 0, row_8 = 0, row_9 = 0, row_10 = 0, row_11 = 0, row_10_bokeya_fine = 0, row_10_khelapi_fine = 0, row_16 = 0;
        var count = 0;

        function isCellEmpty(row, cellClass) {
            // Get the cell element based on the class
            const cell = row.querySelector(`.${cellClass}`);
            return cell ? !cell.textContent.trim() : true; // Return true if empty or not found
        }

        tableRows.forEach(function (row) {
            var category;
            var cells = row.cells;
            var category_sell;

            // Determine which category to check
            if (selectedCategory === 'category1') {
                category_sell = 'category-cell1';
            } else if (selectedCategory === 'category2') {
                category_sell = 'category-cell2';
            } else if (selectedCategory === 'category3') {
                category_sell = 'category-cell3';
            } else if (selectedCategory === 'category4') {
                category_sell = 'category-cell4';
            } else {
                category_sell = '';
            }

            // Check if the cell is empty or has a value
            if (selectedCategory !== 'all' && isCellEmpty(row, category_sell)) {
                row.style.display = 'none'; // Hide row if the category cell is empty
                return; // Skip to the next row
            }

            // If not empty, get the category
            for (var i = 0; i < cells.length; i++) {
                var cell = cells[i];
                if (cell.classList.contains(category_sell)) {
                    category = cell.textContent.trim();
                    break; // Exit loop once category data is found
                }
            }

            if (selectedCategory === 'all' || category === selectedCategory) {
                row.style.display = ''; // Show row if category matches or if all categories are selected
                count += 1;
                var rowNumberCell = row.cells[0]; // Assuming the first cell is for row numbers
                rowNumberCell.textContent = count; // Set the row number (index starts from 0)

                // Process amounts
                var amountCell5 = row.cells[4]; // Adjust index as needed
                var amount5 = parseFloat(amountCell5.textContent.trim());
                if (!isNaN(amount5)) row_5 += amount5;

                var amountCell7 = row.cells[6]; // Adjust index as needed
                var amount7 = parseFloat(amountCell7.textContent.trim());
                if (!isNaN(amount7)) row_7 += amount7;

                var amountCell8 = row.cells[7]; // Adjust index as needed
                var amount8 = parseFloat(amountCell8.textContent.trim());
                if (!isNaN(amount8)) row_8 += amount8;

                var amountCell9 = row.cells[8]; // Adjust index as needed
                var amount9 = parseFloat(amountCell9.textContent.trim());
                if (!isNaN(amount9)) row_9 += amount9;

                var amountCell10 = row.cells[9]; // Adjust index as needed
                var amount10 = parseFloat(amountCell10.textContent.trim());
                if (!isNaN(amount10)) row_10 += amount10;

                var amountCell11 = row.cells[10]; // Adjust index as needed
                var amount11 = parseFloat(amountCell11.textContent.trim());
                if (!isNaN(amount11)) row_11 += amount11;

                var amountCell10_bokeya_fine = row.cells[11]; // Adjust index as needed
                var amount10_bokeya_fine = parseFloat(amountCell10_bokeya_fine.textContent.trim());
                if (!isNaN(amount10_bokeya_fine)) row_10_bokeya_fine += amount10_bokeya_fine;

                var amountCell10_khelapi_fine = row.cells[12]; // Adjust index as needed
                var amount10_khelapi_fine = parseFloat(amountCell10_khelapi_fine.textContent.trim());
                if (!isNaN(amount10_khelapi_fine)) row_10_khelapi_fine += amount10_khelapi_fine;

                var amountCell16 = row.cells[17]; // Adjust index as needed
                var amount16 = parseFloat(amountCell16.textContent.trim());
                if (!isNaN(amount16)) row_16 += amount16;

            } else {
                row.style.display = 'none'; // Hide row if category doesn't match
            }
        });

        // Display or update the total sum somewhere in your HTML
        document.getElementById('row_5').textContent = row_5.toFixed(2); // Update total sum
        document.getElementById('row_7').textContent = row_7.toFixed(2); // Update total sum
        document.getElementById('row_8').textContent = row_8.toFixed(2); // Update total sum
        document.getElementById('row_9').textContent = row_9.toFixed(2); // Update total sum
        document.getElementById('row_10').textContent = row_10.toFixed(2); // Update total sum
        document.getElementById('row_11').textContent = row_11.toFixed(2); // Update total sum
        document.getElementById('row_10_bokeya_fine').textContent = row_10_bokeya_fine.toFixed(2); // Update total sum
        document.getElementById('row_10_khelapi_fine').textContent = row_10_khelapi_fine.toFixed(2); // Update total sum
        document.getElementById('row_16').textContent = row_16.toFixed(2); // Update total sum
    }

    // Add an event listener to the category filter dropdown to trigger the updateSummation function when the category is filtered
    document.getElementById('categoryFilter').addEventListener('change', function () {
        filterTable(); // Call filterTable() to filter the table rows
    });

    function updateSummation() {
        var row_5 = 0;
        var row_7 = 0;
        var row_8 = 0;
        var row_9 = 0;
        var row_10 = 0;
        var row_11 = 0;
        var row_10_bokeya_fine = 0;
        var row_10_khelapi_fine = 0;
        var row_16 = 0;
        var visibleRows = document.querySelectorAll('#dynamicDataBody tr');

        visibleRows.forEach(function (row) {
            // Assuming the amount is stored in the third cell of each row
            var amountCell5 = row.cells[6]; // Adjust index as needed
            var amount5 = parseFloat(amountCell5.textContent.trim());

            if (!isNaN(amount5)) {
                row_5 += amount5;
            }
            // Assuming the amount is stored in the third cell of each row
            var amountCell7 = row.cells[8]; // Adjust index as needed
            var amount7 = parseFloat(amountCell7.textContent.trim());

            if (!isNaN(amount7)) {
                row_7 += amount7;
            }

            // Assuming the amount is stored in the third cell of each row
            var amountCell8 = row.cells[9]; // Adjust index as needed
            var amount8 = parseFloat(amountCell8.textContent.trim());

            if (!isNaN(amount8)) {
                row_8 += amount8;
            }

            // Assuming the amount is stored in the third cell of each row
            var amountCell9 = row.cells[10]; // Adjust index as needed
            var amount9 = parseFloat(amountCell9.textContent.trim());

            if (!isNaN(amount9)) {
                row_9 += amount9;
            }
            // Assuming the amount is stored in the third cell of each row
            var amountCell10 = row.cells[11]; // Adjust index as needed
            var amount10 = parseFloat(amountCell10.textContent.trim());

            if (!isNaN(amount10)) {
                row_10 += amount10;
            }
            // Assuming the amount is stored in the third cell of each row
            var amountCell11 = row.cells[12]; // Adjust index as needed
            var amount11 = parseFloat(amountCell11.textContent.trim());

            if (!isNaN(amount11)) {
                row_11 += amount11;
            }

            // Assuming the amount is stored in the third cell of each row
            var amountCell10_bokeya_fine = row.cells[13]; // Adjust index as needed
            var amount10_bokeya_fine = parseFloat(amountCell10_bokeya_fine.textContent.trim());

            if (!isNaN(amount10_bokeya_fine)) {
                row_10_bokeya_fine += amount10_bokeya_fine;
            }
            // Assuming the amount is stored in the third cell of each row
            var amountCell10_khelapi_fine = row.cells[14]; // Adjust index as needed
            var amount10_khelapi_fine = parseFloat(amountCell10_khelapi_fine.textContent.trim());

            if (!isNaN(amount10_khelapi_fine)) {
                row_10_khelapi_fine += amount10_khelapi_fine;
            }
            // Assuming the amount is stored in the third cell of each row
            var amountCell16 = row.cells[19]; // Adjust index as needed
            var amount16 = parseFloat(amountCell16.textContent.trim());

            if (!isNaN(amount16)) {
                row_16 += amount16;
            }
        });

        // Display or update the total sum somewhere in your HTML, e.g., <div id="totalSum"></div>
        document.getElementById('row_5').textContent = row_5.toFixed(2); // Update total sum
        document.getElementById('row_7').textContent = row_7.toFixed(2); // Update total sum
        document.getElementById('row_8').textContent = row_8.toFixed(2); // Update total sum
        document.getElementById('row_9').textContent = row_9.toFixed(2); // Update total sum
        document.getElementById('row_10').textContent = row_10.toFixed(2); // Update total sum
        document.getElementById('row_11').textContent = row_11.toFixed(2); // Update total sum
        document.getElementById('row_10_bokeya_fine').textContent = row_10_bokeya_fine.toFixed(2); // Update total sum
        document.getElementById('row_10_khelapi_fine').textContent = row_10_khelapi_fine.toFixed(2); // Update total sum
        document.getElementById('row_16').textContent = row_16.toFixed(2); // Update total sum
    }

</script>

