<script type="text/javascript">

    var now = new Date();
        var year = now.getFullYear();
        var month = now.toLocaleString('default', { month: 'long' });
        var day = String(now.getDate()).padStart(2, '0');
        var hours = String(now.getHours()).padStart(2, '0');
    $(document).ready(function () {
        // document.getElementById('month_num').value = '</?= $month_num ?>';
        // document.getElementById('year').value = '</?= $year ?>';

        $("#banner_show").hide();
        $("#card_title_hide").hide();
    });

    function printDiv(divName) {
        $(".action").hide();
        var printContents = document.getElementById(divName).innerHTML;
        var originalContents = document.body.innerHTML;

        // Create a new window for printing
        var printWindow = window.open('', '', 'height=1600,width=1600');

        // Create a hidden print-preview container to apply media print styles
        var printPreviewContainer = document.createElement('div');
        printPreviewContainer.style.position = 'absolute';
        printPreviewContainer.style.left = '-9999px'; // Hide it off-screen
        printPreviewContainer.style.visibility = 'hidden'; // Make it invisible
        document.body.appendChild(printPreviewContainer);

        // Add styles to the print-preview container
        var printPreviewstyles = `
        <style>
            table {
                width: 100%;
                border-collapse: collapse;
            }
            th, td {
                border: 1px solid black !important;
                padding: 2px important;
            }
            th {
                font-size: 9px !important;
                background-color: #B6DDE8 !important;
            }
            td {
                font-size: 9px !important;
            }
            .truncated {
                /* display: inline-block; */
                max-width: 50px; /* Adjust as needed */
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
                cursor: pointer; /* Indicate that text can be interacted with */
            }

            .full-text {
                display: none;
            }

            .truncated:hover .full-text,
            .truncated.clicked .full-text {
                display: inline;
            }
            abbr[title] {
                text-decoration: unset;
            }
            .truncated-text-hide {
                display: none;
            }

           
        </style>
    `;
        printPreviewContainer.innerHTML = printPreviewstyles;

        // Create a print-preview container and append it to the document body
        var printPreview = document.createElement('div');
        printPreview.innerHTML = printContents;
        printPreviewContainer.appendChild(printPreview);

        // Split tables and determine pagination
        var tables = Array.from(printPreview.querySelectorAll('table'));
        var firstTwoTables = tables.slice(0, 3);
        var printPreviewTable = tables[3];

        // Measure the heights of the tables and rows
        function tableHeight(element) {
            var tempElement = document.createElement('div');
            tempElement.innerHTML = element.outerHTML;
            printPreviewContainer.appendChild(tempElement);
            var height = tempElement.getBoundingClientRect().height;
            printPreviewContainer.removeChild(tempElement);
            return height;
        }
        var first_table_height = tableHeight(tables[0]);

        // Measure the heights of the rows from the print-preview table
        var rows = Array.from(printPreviewTable.querySelectorAll('tr'));
        function measureRowHeights(rows) {
            return rows.map(row => {

                var height = 40;
                return height;
            });
        }
        var rowHeights = measureRowHeights(rows);

        var currentRow = 0;
        var totalPages = 0;
        var isFirstPage = true;

        // Calculate page dimensions
        var pageHeight = 1400; // A4 height in pixels (landscape)
        var headerHeight = 220; // Approximate height of the header in pixels
        var availableHeightWithoutHeader = pageHeight;
        var availableHeightWithHeader = availableHeightWithoutHeader - headerHeight - first_table_height;

        // Store the number of rows for each page
        var rowsPerPage = [];
        var pageContentHeight;

        // Calculate number of rows per page
        while (currentRow < rows.length) {
            pageContentHeight = isFirstPage ? availableHeightWithHeader : availableHeightWithoutHeader;

            var pageRows = 0;

            while (currentRow < rows.length && rowHeights[currentRow] <= pageContentHeight) {
                pageContentHeight -= rowHeights[currentRow];
                pageRows++;
                currentRow++;
            }
            rowsPerPage.push(pageRows);
